def AKLT.Blueprint.H3.RawSuccessorStatement : Prop :=
∀ m : ℕ, 1 ≤ m → ∀ w : DirectionWord m, RawWindow w →
    ∀ d : Compass, WindowAdmissible w d → RawWindow (windowSuccessor w d)

def AKLT.Blueprint.H3.ProjectionRealizationStatement : Prop :=
∀ m q : ℕ, 1 ≤ m → ∀ π : DirectionWord m → Fin q, CompatibleProjection m q π →
    ∃ Q : MemoryQuotient m q, Q.Correct ∧ ∀ w, RawWindow w → Q.project w = π w

def AKLT.Blueprint.H3.ExposureListExpansionStatement : Prop :=
∀ n : ℕ, ∀ w : DirectionWord n, ∀ reward : Fin n → ℚ, ∀ l : List (Fin n), l.Nodup →
    exposureSum w reward l = ∑ j ∈ l.toFinset, reward j * orderedMultiplier w l j

def AKLT.Blueprint.H3.IncidentBondBudgetStatement : Prop :=
∀ n : ℕ, ∀ w : DirectionWord n, IsTrail kernelStart kernelIncoming w → ∀ z : Plane,
    departureCount kernelStart w n z + arrivalCount w z ≤ 4

def AKLT.Blueprint.H3.DepartureBalanceStatement : Prop :=
∀ n : ℕ, ∀ w : DirectionWord n, ∀ z : Plane,
    departureCount kernelStart w n z ≤ arrivalCount w z + 1

def AKLT.Blueprint.H3.LongTrailPrefixStatement : Prop :=
∀ X : PairType, ∀ d₀ : Compass, ∀ n : ℕ, 12 < n → ∀ w : DirectionWord n,
    ClosedTrail X w → FirstDirection w d₀ → SurvivingPrefix X d₀ (takeWord w 12)

def AKLT.Blueprint.H3.ReflectionLivePairsStatement : Prop :=
∀ n : ℕ, ∀ w : DirectionWord n, ∀ i : Fin n,
    (responsePairs w i).image (fun p => p.image reflectSite) = responsePairs (reflectWord w) i

def AKLT.Blueprint.H3.StationaryCertificateBridgeStatementV2 : Prop :=
∀ m q : ℕ, ∀ Q : MemoryQuotient m q, ∀ X : PairType, ∀ d₀ : Compass,
    ∀ C : StationaryData q, C.PassesV2 Q X d₀ → C.Passes Q X d₀
